          color: 'bg-amber-500',
          icon: AlertTriangle,
          label: 'MONITORED USE',
          textColor: 'text-amber-700',
          borderColor: 'border-amber-200',
          bgColor: 'bg-amber-50'
        };
      case 'high':
        return {
          color: 'bg-orange-500',
          icon: AlertTriangle,
          label: 'REQUIRES REVIEW',
          textColor: 'text-orange-700',
          borderColor: 'border-orange-200',
          bgColor: 'bg-orange-50'
