@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  /* TrustVerify Logo-Based Color System */
  --primary: #0A3778; /* Trust Navy from logo */
  --primary-hover: #0D4594;
  --primary-light: #E8F0FB;
  --primary-subtle: #F4F7FD;
  --secondary: #1DBF73; /* Verify Teal from logo */
  --secondary-hover: #17A362;
  --secondary-light: #E6F9F1;
  --secondary-subtle: #F0FDF7;
  --success: #059669;
  --success-hover: #047857;
  --success-light: #D1FAE5;
  --success-subtle: #ECFDF5;
  --warning: #FFB400; /* Alert Amber - risk highlight */
  --warning-hover: #E6A200;
  --warning-light: #FFF4E6;
  --warning-subtle: #FFFCF0;
  --error: #DC2626;
  --error-hover: #B91C1C;
  --error-light: #FEE2E2;
  --error-subtle: #FEF2F2;
  --background: #F8FAFC;
  --surface: #FFFFFF;
  --surface-raised: #FFFFFF;
  --text-primary: #0F172A;
  --text-secondary: #334155;
  --text-muted: #64748B;
  --text-inverse: #FFFFFF;
  --border: #E2E8F0;
  --border-light: #F1F5F9;
  --border-subtle: #F8FAFC;

  /* Spacing System - Professional SaaS Standards */
  --spacing-xs: 8px;
  --spacing-sm: 16px;
  --spacing-md: 24px;
  --spacing-lg: 32px;
  --spacing-xl: 40px;
  --spacing-2xl: 48px;
  --spacing-3xl: 64px;

  /* Shadows & Effects */
  --shadow-sm: 0 1px 2px 0 rgba(0, 51, 102, 0.05);
  --shadow: 0 1px 3px 0 rgba(0, 51, 102, 0.1), 0 1px 2px -1px rgba(0, 51, 102, 0.1);

  /* Additional Design Variables - USP Theme */
  --gradient-hero: linear-gradient(135deg, #003366 0%, #00C2A8 100%);
  --gradient-cta: linear-gradient(135deg, #00C2A8 0%, #003366 100%);
  --accent: #FFB400; /* Alert Amber */
  --accent-subtle: #FFF4E6;
}

/* Global Font Rendering - Crisp Text */
* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

img {
  image-rendering: -webkit-optimize-contrast;
  image-rendering: crisp-edges;
  backface-visibility: hidden;
  transform: translateZ(0);
}

/* Text Content Containment Utilities */
.text-truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.text-break {
  word-break: break-word;
  overflow-wrap: break-word;
}

.text-contain {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

/* Multi-line text truncation */
.line-clamp-1 {
  display: -webkit-box;
  -webkit-line-clamp: 1;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

.line-clamp-3 {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Container utilities for content containment */
.content-container {
  min-width: 0;
  overflow: hidden;
}

.flex-container {
  display: flex;
  min-width: 0;
  overflow: hidden;
}

.flex-item-shrink {
  flex-shrink: 0;
}

.flex-item-grow {
  flex: 1;
  min-width: 0;
  overflow: hidden;
}

/* Email and long text specific utilities */
.email-container {
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 768px) {
  .email-container {
    max-width: 150px;
  }
}

/* Card content utilities */
.card-content-safe {
  overflow: hidden;
  word-wrap: break-word;
  word-break: break-word;
}

.button-text-safe {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100px;
}

@media (max-width: 640px) {
  .button-text-safe {
    max-width: 80px;
  }
}

* {
  box-sizing: border-box;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  background-color: var(--background);
  color: var(--text-primary);
  line-height: 1.7;
  font-size: 16px;
  font-weight: 400;
  margin: 0;
  padding: 0;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Professional Layout System */
.tv-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

.tv-page-wrapper {
  min-height: 100vh;
  background-color: var(--background);
  padding-top: 80px; /* Fixed navigation height */
}

/* Responsive text handling */
.responsive-text {
  word-wrap: break-word;
  overflow-wrap: break-word;
  hyphens: auto;
}

/* Card content responsive handling */
.tv-card {
  word-wrap: break-word;
  overflow-wrap: break-word;
}

.tv-card * {
  max-width: 100%;
  word-wrap: break-word;
  overflow-wrap: break-word;
}

/* Dropdown improvements */
[data-radix-popper-content-wrapper] {
  z-index: 9999 !important;
}

/* Mobile responsive improvements */
@media (max-width: 768px) {
  .tv-container {
    padding: 0 var(--spacing-sm);
  }

  .grid-responsive {
    grid-template-columns: 1fr !important;
    gap: 1rem !important;
  }

  .text-responsive {
    font-size: 14px !important;
    line-height: 1.4 !important;
  }

  .button-responsive {
    padding: 0.5rem 1rem !important;
    font-size: 14px !important;
  }
}

.tv-content-area {
  background-color: var(--surface);
  border-radius: 16px;
  padding: var(--spacing-xl);
  margin: var(--spacing-lg) 0;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
}

.tv-section {
  margin-bottom: var(--spacing-3xl);
}

.tv-section:last-child {
  margin-bottom: 0;
}

/* Professional Grid System */
.tv-grid {
  display: grid;
  gap: var(--spacing-lg);
}

.tv-grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.tv-grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
}

.tv-grid-4 {
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

/* Z-index System */
.z-navigation { z-index: 1000; }
.z-modal { z-index: 2000; }
.z-dropdown { z-index: 1500; }
.z-overlay { z-index: 1100; }

/* Animation System */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(20px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.tv-animate-fade-in-up {
  animation: fadeInUp 0.6s ease-out;
}

.tv-animate-fade-in {
  animation: fadeIn 0.4s ease-out;
}

.tv-animate-slide-in-right {
  animation: slideInRight 0.4s ease-out;
}

/* Enhanced Card System */
.tv-card {
  background-color: var(--surface);
  border-radius: 1rem;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  transition: all 0.3s ease;
}

.tv-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.tv-card-elevated {
  box-shadow: var(--shadow-lg);
}

.tv-card-elevated:hover {
  box-shadow: var(--shadow-xl);
  transform: translateY(-8px);
}

/* Responsive Design System */
@media (max-width: 1024px) {
  .tv-container {
    padding: 0 var(--spacing-sm);
  }

  .tv-heading-1 {
    font-size: 2.5rem;
  }

  .tv-heading-2 {
    font-size: 2rem;
  }

  .tv-page-wrapper {
    padding-top: 80px;
  }
}

@media (max-width: 768px) {
  .tv-container {
    padding: 0 var(--spacing-sm);
  }

  .tv-heading-1 {
    font-size: 2rem;
  }

  .tv-heading-2 {
    font-size: 1.75rem;
  }

  .tv-heading-3 {
    font-size: 1.5rem;
  }

  .tv-content-area {
    padding: var(--spacing-lg);
    margin: var(--spacing-sm) 0;
  }

  .tv-btn-large {
    padding: var(--spacing-sm) var(--spacing-lg);
    font-size: 16px;
    min-height: 48px;
  }

  .tv-grid-2,
  .tv-grid-3,
  .tv-grid-4 {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  body {
    font-size: 16px;
  }

  .tv-heading-1 {
    font-size: 1.75rem;
  }

  .tv-heading-2 {
    font-size: 1.5rem;
  }

  .tv-body-large {
    font-size: 18px;
  }

  .tv-content-area {
    padding: var(--spacing-md);
  }
}

/* Professional Typography System */
.tv-heading-1 {
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 1.1;
  color: var(--text-primary);
  margin-bottom: var(--spacing-md);
}

.tv-heading-2 {
  font-size: 2.75rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
  margin-bottom: var(--spacing-md);
}

.tv-heading-3 {
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-primary);
  margin-bottom: var(--spacing-sm);
}

.tv-heading-4 {
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text-primary);
  margin-bottom: var(--spacing-sm);
}

.tv-heading-5 {
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text-primary);
  margin-bottom: var(--spacing-xs);
}

.tv-body-large {
  font-size: 20px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: var(--spacing-md);
}

.tv-body {
  font-size: 18px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-bottom: var(--spacing-sm);
}

.tv-body-small {
  font-size: 16px;
  line-height: 1.5;
  color: var(--text-muted);
}

/* Professional Button System */
.tv-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: var(--spacing-sm) var(--spacing-md);
  font-weight: 600;
  border-radius: 12px;
  transition: all 0.2s ease-in-out;
  text-decoration: none;
  cursor: pointer;
  border: none;
  font-size: 16px;
  line-height: 1.5;
  min-height: 48px;
  gap: var(--spacing-xs);
}

.tv-btn-large {
  padding: var(--spacing-md) var(--spacing-xl);
  font-size: 18px;
  min-height: 56px;
  border-radius: 16px;
}

.tv-btn-primary {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-hover) 100%);
  color: var(--text-inverse);
  box-shadow: 0 2px 8px rgba(30, 58, 138, 0.25);
  font-weight: 600;
}

.tv-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(30, 58, 138, 0.35);
}

.tv-btn-secondary {
  background-color: var(--surface);
  color: var(--primary);
  border: 2px solid var(--primary);
}

.tv-btn-secondary:hover {
  background-color: var(--primary-subtle);
  transform: translateY(-1px);
}

.tv-btn-ghost {
  background-color: transparent;
  color: var(--text-secondary);
  border: 2px solid var(--border);
}

.tv-btn-ghost:hover {
  background-color: var(--surface);
  border-color: var(--primary);
  color: var(--primary);
}

.tv-btn-secondary {
  background-color: var(--surface);
  color: var(--primary);
  border: 2px solid var(--primary);
}

.tv-btn-secondary:hover {
  background-color: var(--primary-subtle);
  transform: translateY(-1px);
}

.tv-btn-accent {
  background-color: var(--accent);
  color: white;
}

.tv-btn-accent:hover {
  background-color: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-lg);
}

/* Card Components */
.tv-card {
  background-color: var(--background);
  border-radius: 1rem;
  box-shadow: var(--shadow-md);
  overflow: hidden;
  transition: all 0.3s ease;
}

.tv-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.tv-card-header {
  background-color: var(--primary);
  color: white;
  padding: 1.5rem;
}

.tv-card-content {
  padding: 1.5rem;
  background-color: var(--background);
}

/* Navigation */
.tv-nav {
  background-color: var(--background);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(8px);
}

.tv-nav-link {
  color: var(--text-secondary);
  font-weight: 500;
  transition: color 0.2s ease;
  text-decoration: none;
}

.tv-nav-link:hover {
  color: var(--primary);
}

/* Container */
.tv-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1rem;
}

/* Responsive Grid */
.tv-grid {
  display: grid;
  gap: 1.5rem;
}

.tv-grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.tv-grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
}

.tv-grid-4 {
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

/* Utilities */
.text-primary { color: var(--primary); }
.text-accent { color: var(--accent); }
.text-muted { color: var(--text-muted); }
.bg-primary { background-color: var(--primary); }
.bg-accent { background-color: var(--accent); }
.bg-light { background-color: var(--background-light); }

/* Status Badges */
.status-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.25rem 0.75rem;
  border-radius: 9999px;
  font-size: 0.875rem;
  font-weight: 500;
}

.status-badge.pending {
  background-color: #FEF3C7;
  color: #92400E;
}

.status-badge.approved {
  background-color: var(--accent-light);
  color: var(--accent-hover);
}

.status-badge.rejected {
  background-color: #FEE2E2;
  color: #DC2626;
}

.status-badge.active {
  background-color: var(--primary-light);
  color: var(--primary-hover);
}

.status-badge.completed {
  background-color: var(--accent-light);
  color: var(--accent-hover);
}

/* Legacy compatibility for old classes */
.bg-navy { background-color: var(--primary); }
.text-navy { color: var(--primary); }
.text-golden { color: var(--accent); }
.bg-mist { background-color: var(--background-light); }

.tv-heading-1 {
  font-family: 'Inter', sans-serif;
  font-size: 3.5rem;
  font-weight: 800;
  line-height: 1.1;
  color: var(--nightsky-navy);
  margin: 0;
  letter-spacing: -0.02em;
}

.tv-heading-2 {
  font-family: 'Inter', sans-serif;
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1.2;
  color: var(--nightsky-navy);
  margin: 0;
  letter-spacing: -0.01em;
}

.tv-heading-3 {
  font-family: 'Inter', sans-serif;
  font-size: 1.875rem;
  font-weight: 600;
  line-height: 1.3;
  color: var(--nightsky-navy);
  margin: 0;
}

.tv-heading-4 {
  font-family: 'Inter', sans-serif;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--nightsky-navy);
  margin: 0;
}

.tv-body {
  font-family: 'Inter', sans-serif;
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.6;
  color: var(--slate-grey);
  margin: 0;
}

.tv-body-sm {
  font-family: 'Inter', sans-serif;
  font-size: 0.875rem;
  font-weight: 400;
  line-height: 1.5;
  color: var(--slate-grey);
  margin: 0;
}

/* Fancy Button System */
.tv-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem 2rem;
  border-radius: 8px;
  font-family: 'Inter', sans-serif;
  font-size: 0.9375rem;
  font-weight: 600;
  text-decoration: none;
  border: none;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
  outline: none;
  transform: translateY(0);
}

.tv-btn:before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  transition: left 0.5s;
}

.tv-btn:hover:before {
  left: 100%;
}

.tv-btn-primary {
  background: var(--gradient-golden);
  color: var(--pure-white);
  box-shadow: var(--shadow-golden);
  border: 2px solid transparent;
}

.tv-btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-golden-lg);
  background: linear-gradient(135deg, #C19660 0%, #B8875A 100%);
}

.tv-btn-primary:active {
  transform: translateY(0);
  box-shadow: var(--shadow-golden);
}

.tv-btn-secondary {
  background: var(--gradient-navy);
  color: var(--pure-white);
  box-shadow: var(--shadow-md);
  border: 2px solid transparent;
}

.tv-btn-secondary:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
  background: linear-gradient(135deg, #1A2A3F 0%, #243447 100%);
}

.tv-btn-outline {
  background: transparent;
  color: var(--nightsky-navy);
  border: 2px solid var(--nightsky-navy);
  box-shadow: var(--shadow);
}

.tv-btn-outline:hover {
  background: var(--nightsky-navy);
  color: var(--pure-white);
  transform: translateY(-2px);
  box-shadow: var(--shadow-lg);
}

.tv-btn-golden-outline {
  background: transparent;
  color: var(--golden-trust);
  border: 2px solid var(--golden-trust);
  box-shadow: var(--shadow);
}

.tv-btn-golden-outline:hover {
  background: var(--golden-trust);
  color: var(--pure-white);
  transform: translateY(-2px);
  box-shadow: var(--shadow-golden-lg);
}

.tv-btn-success {
  background: linear-gradient(135deg, var(--success) 0%, #059669 100%);
  color: var(--pure-white);
  box-shadow: 0 4px 14px 0 rgba(16, 185, 129, 0.25);
}

.tv-btn-warning {
  background: linear-gradient(135deg, var(--warning) 0%, #D97706 100%);
  color: var(--pure-white);
  box-shadow: 0 4px 14px 0 rgba(245, 158, 11, 0.25);
}

.tv-btn-error {
  background: linear-gradient(135deg, var(--error) 0%, #DC2626 100%);
  color: var(--pure-white);
  box-shadow: 0 4px 14px 0 rgba(239, 68, 68, 0.25);
}

.tv-btn-lg {
  padding: 1rem 2.5rem;
  font-size: 1.125rem;
}

.tv-btn-sm {
  padding: 0.5rem 1.5rem;
  font-size: 0.875rem;
}

/* Card System */
.tv-card {
  background: var(--pure-white);
  border-radius: 12px;
  box-shadow: var(--shadow);
  border: 1px solid rgba(46, 58, 70, 0.08);
  transition: all 0.3s ease;
  overflow: hidden;
}

.tv-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.tv-card-header {
  padding: 1.5rem;
  background: var(--nightsky-navy);
  color: var(--pure-white);
}

.tv-card-header h3 {
  color: var(--pure-white);
  margin: 0;
}

.tv-card-content {
  padding: 1.5rem;
}

.tv-card-mist {
  background: var(--mist-white);
  border: 1px solid rgba(46, 58, 70, 0.12);
}

/* Trust Badge System */
.tv-trust-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  background: var(--gradient-golden);
  border-radius: 50%;
  box-shadow: var(--shadow-golden);
  color: var(--pure-white);
  font-size: 1.25rem;
  transition: all 0.3s ease;
}

.tv-trust-badge:hover {
  transform: scale(1.1);
  box-shadow: var(--shadow-golden-lg);
}

/* Navigation */
.tv-nav {
  background: var(--pure-white);
  border-bottom: 1px solid rgba(46, 58, 70, 0.1);
  box-shadow: var(--shadow-sm);
  backdrop-filter: blur(8px);
}

.tv-nav-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  color: var(--slate-grey);
  text-decoration: none;
  font-weight: 500;
  border-radius: 6px;
  transition: all 0.2s ease;
}

.tv-nav-link:hover {
  color: var(--golden-trust);
  background: rgba(212, 163, 115, 0.08);
}

.tv-nav-link.active {
  color: var(--golden-trust);
  background: rgba(212, 163, 115, 0.12);
  font-weight: 600;
}

/* Sidebar Navigation */
.tv-sidebar {
  background: var(--nightsky-navy);
  color: var(--pure-white);
  width: 16rem;
  height: 100vh;
  position: fixed;
  left: 0;
  top: 0;
  overflow-y: auto;
  z-index: 40;
}

.tv-sidebar-link {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1.5rem;
  color: rgba(255, 255, 255, 0.8);
  text-decoration: none;
  font-weight: 500;
  transition: all 0.2s ease;
  border-left: 3px solid transparent;
}

.tv-sidebar-link:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--pure-white);
}

.tv-sidebar-link.active {
  background: rgba(212, 163, 115, 0.15);
  color: var(--golden-trust);
  border-left-color: var(--golden-trust);
  font-weight: 600;
}

/* Input System */
.tv-input {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 2px solid rgba(46, 58, 70, 0.15);
  border-radius: 8px;
  background: var(--pure-white);
  color: var(--slate-grey);
  font-family: 'Inter', sans-serif;
  font-size: 0.9375rem;
  transition: all 0.2s ease;
  outline: none;
}

.tv-input:focus {
  border-color: var(--golden-trust);
  box-shadow: 0 0 0 3px rgba(212, 163, 115, 0.1);
}

.tv-input::placeholder {
  color: rgba(46, 58, 70, 0.5);
}

/* Status Badges */
.tv-status-success {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.75rem;
  background: rgba(16, 185, 129, 0.1);
  color: var(--success);
  border: 1px solid rgba(16, 185, 129, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
}

.tv-status-warning {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.75rem;
  background: rgba(245, 158, 11, 0.1);
  color: var(--warning);
  border: 1px solid rgba(245, 158, 11, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
}

.tv-status-error {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.75rem;
  background: rgba(239, 68, 68, 0.1);
  color: var(--error);
  border: 1px solid rgba(239, 68, 68, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
}

.tv-status-pending {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem 0.75rem;
  background: rgba(59, 130, 246, 0.1);
  color: var(--info);
  border: 1px solid rgba(59, 130, 246, 0.2);
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 600;
}

/* Layout System */
.tv-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.tv-grid {
  display: grid;
  gap: 1.5rem;
}

.tv-section {
  padding: 5rem 0;
}

/* Hero Section */
.tv-hero {
  background: var(--gradient-hero);
  color: var(--pure-white);
  padding: 7.5rem 0;
  position: relative;
  overflow: hidden;
}

.tv-hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.03'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E") repeat;
  opacity: 0.4;
}

.tv-hero * {
  position: relative;
  z-index: 1;
}

/* Stats Section */
.tv-stats {
  background: var(--pure-white);
  padding: 4rem 0;
  border-top: 1px solid rgba(46, 58, 70, 0.08);
  border-bottom: 1px solid rgba(46, 58, 70, 0.08);
}

/* Responsive Design */
@media (max-width: 768px) {
  .tv-heading-1 {
    font-size: 2.5rem;
  }

  .tv-heading-2 {
    font-size: 2rem;
  }

  .tv-container {
    padding: 0 1rem;
  }

  .tv-section {
    padding: 3rem 0;
  }

  .tv-hero {
    padding: 5rem 0;
  }

  .tv-sidebar {
    width: 100%;
    height: auto;
    position: static;
  }
}

@media (max-width: 480px) {
  .tv-heading-1 {
    font-size: 2rem;
  }

  .tv-btn {
    padding: 0.75rem 1.5rem;
    font-size: 0.875rem;
  }

  .tv-btn-lg {
    padding: 0.875rem 2rem;
    font-size: 1rem;
  }
}

/* Utility Classes */
.text-navy { color: var(--nightsky-navy) !important; }
.text-golden { color: var(--golden-trust) !important; }
.text-slate { color: var(--slate-grey) !important; }
.text-white { color: var(--pure-white) !important; }

.bg-navy { background-color: var(--nightsky-navy) !important; }
.bg-golden { background-color: var(--golden-trust) !important; }
.bg-mist { background-color: var(--mist-white) !important; }
.bg-white { background-color: var(--pure-white) !important; }

.border-navy { border-color: var(--nightsky-navy) !important; }
.border-golden { border-color: var(--golden-trust) !important; }

/* Responsive utilities for transaction forms */
.form-field-container {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.email-input {
  width: 100%;
  padding-right: 1rem;
  text-overflow: ellipsis;
  overflow: hidden;
  white-space: nowrap;
}

.dropdown-content {
  min-width: 200px;
  max-width: 300px;
  z-index: 50;
}

.transaction-card {
  overflow: hidden;
}

.transaction-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.transaction-content {
  min-width: 0;
  flex: 1;
}

.transaction-actions {
  flex-shrink: 0;
}

/* Text truncation utilities */
.truncate-email {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

/* Mobile email container fixes */
.mobile-email-container {
  word-break: break-all;
  overflow-wrap: break-word;
  hyphens: auto;
  max-width: 100%;
  display: inline-block;
}

@media (max-width: 640px) {
  .mobile-email-container {
    font-size: 0.875rem;
    line-height: 1.25rem;
    max-width: 150px;
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
  }
}

@media (max-width: 480px) {
  .mobile-email-container {
    max-width: 100px;
    font-size: 0.8125rem;
  }
}

/* Responsive grid improvements */
.responsive-form-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .responsive-form-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@layer utilities {
  .email-container {
    @apply truncate max-w-[120px] sm:max-w-[200px] md:max-w-none;
  }

  .text-truncate {
    @apply truncate;
  }

  .xs\:inline {
    @media (min-width: 475px) {
      @apply inline;
    }
  }

  .xs\:hidden {
    @media (min-width: 475px) {
      @apply hidden;
    }
  }
}

