    it('applies Emerald Green accent color correctly', () => {
      const mockUser = {
        id: 1,
        username: 'testuser',
        trustScore: '95',
        verificationLevel: 'verified',
        isAdmin: false,
      }

      render(
        <TestWrapper user={mockUser}>
          <HomePage />
