                      </div>
                    </CardContent>
                  </Card>
                )}

                {/* Warnings */}
                {securityMetrics.warnings.length > 0 && (
                  <Card>
                    <CardHeader>
                      <CardTitle className="text-yellow-600 flex items-center">
                        <AlertTriangle className="h-5 w-5 mr-2" />
