import { Request, Response, NextFunction } from 'express';
import { User } from '@shared/schema';
import pino from 'pino';

const logger = pino({
  name: 'rbac',
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug'
});

// Define roles and permissions
export enum Role {
  USER = 'user',
  MODERATOR = 'moderator',
  ADMIN = 'admin',
  SUPER_ADMIN = 'super_admin'
}

export enum Permission {
  // User permissions
  READ_OWN_PROFILE = 'read:own_profile',
  UPDATE_OWN_PROFILE = 'update:own_profile',
  CREATE_TRANSACTION = 'create:transaction',
  READ_OWN_TRANSACTIONS = 'read:own_transactions',
  UPDATE_OWN_TRANSACTIONS = 'update:own_transactions',
  CREATE_MESSAGE = 'create:message',
  READ_OWN_MESSAGES = 'read:own_messages',
  CREATE_SCAM_REPORT = 'create:scam_report',
  READ_SCAM_REPORTS = 'read:scam_reports',

  // Moderator permissions
  READ_ALL_TRANSACTIONS = 'read:all_transactions',
  UPDATE_TRANSACTION_STATUS = 'update:transaction_status',
  READ_ALL_MESSAGES = 'read:all_messages',
  MODERATE_MESSAGES = 'moderate:messages',
  REVIEW_SCAM_REPORTS = 'review:scam_reports',
  UPDATE_SCAM_REPORTS = 'update:scam_reports',
  READ_KYC_VERIFICATIONS = 'read:kyc_verifications',
  REVIEW_KYC = 'review:kyc',

  // Admin permissions
  READ_ALL_USERS = 'read:all_users',
  UPDATE_USER_STATUS = 'update:user_status',
  DELETE_USERS = 'delete:users',
  READ_DISPUTES = 'read:disputes',
  RESOLVE_DISPUTES = 'resolve:disputes',
  ACCESS_ADMIN_DASHBOARD = 'access:admin_dashboard',
  MANAGE_DEVELOPER_ACCOUNTS = 'manage:developer_accounts',

  // Super Admin permissions
  MANAGE_SYSTEM_CONFIG = 'manage:system_config',
  ACCESS_AUDIT_LOGS = 'access:audit_logs',
  MANAGE_ROLES = 'manage:roles',
  EMERGENCY_ACCESS = 'emergency:access'
}

// Role-Permission mapping
const rolePermissions: Record<Role, Permission[]> = {
  [Role.USER]: [
    Permission.READ_OWN_PROFILE,
    Permission.UPDATE_OWN_PROFILE,
    Permission.CREATE_TRANSACTION,
    Permission.READ_OWN_TRANSACTIONS,
    Permission.UPDATE_OWN_TRANSACTIONS,
    Permission.CREATE_MESSAGE,
    Permission.READ_OWN_MESSAGES,
    Permission.CREATE_SCAM_REPORT,
    Permission.READ_SCAM_REPORTS
  ],
  [Role.MODERATOR]: [
    // Inherit all user permissions
    ...rolePermissions[Role.USER] || [],
    Permission.READ_ALL_TRANSACTIONS,
    Permission.UPDATE_TRANSACTION_STATUS,
    Permission.READ_ALL_MESSAGES,
    Permission.MODERATE_MESSAGES,
    Permission.REVIEW_SCAM_REPORTS,
    Permission.UPDATE_SCAM_REPORTS,
    Permission.READ_KYC_VERIFICATIONS,
    Permission.REVIEW_KYC
  ],
  [Role.ADMIN]: [
    // Inherit all moderator permissions
    ...rolePermissions[Role.MODERATOR] || [],
    Permission.READ_ALL_USERS,
    Permission.UPDATE_USER_STATUS,
    Permission.READ_DISPUTES,
    Permission.RESOLVE_DISPUTES,
    Permission.ACCESS_ADMIN_DASHBOARD,
    Permission.MANAGE_DEVELOPER_ACCOUNTS
  ],
  [Role.SUPER_ADMIN]: [
    // Inherit all admin permissions
    ...rolePermissions[Role.ADMIN] || [],
    Permission.DELETE_USERS,
    Permission.MANAGE_SYSTEM_CONFIG,
    Permission.ACCESS_AUDIT_LOGS,
    Permission.MANAGE_ROLES,
    Permission.EMERGENCY_ACCESS
  ]
};

// Initialize role permissions properly
rolePermissions[Role.MODERATOR] = [
  ...rolePermissions[Role.USER],
  Permission.READ_ALL_TRANSACTIONS,
  Permission.UPDATE_TRANSACTION_STATUS,
  Permission.READ_ALL_MESSAGES,
  Permission.MODERATE_MESSAGES,
  Permission.REVIEW_SCAM_REPORTS,
  Permission.UPDATE_SCAM_REPORTS,
  Permission.READ_KYC_VERIFICATIONS,
  Permission.REVIEW_KYC
];

rolePermissions[Role.ADMIN] = [
  ...rolePermissions[Role.MODERATOR],
  Permission.READ_ALL_USERS,
  Permission.UPDATE_USER_STATUS,
  Permission.READ_DISPUTES,
  Permission.RESOLVE_DISPUTES,
  Permission.ACCESS_ADMIN_DASHBOARD,
  Permission.MANAGE_DEVELOPER_ACCOUNTS
];

rolePermissions[Role.SUPER_ADMIN] = [
  ...rolePermissions[Role.ADMIN],
  Permission.DELETE_USERS,
  Permission.MANAGE_SYSTEM_CONFIG,
  Permission.ACCESS_AUDIT_LOGS,
  Permission.MANAGE_ROLES,
  Permission.EMERGENCY_ACCESS
];

export class RBACService {
  static getUserRole(user: User): Role {
    // Default role assignment logic
    if (user.email === 'admin@trustverify.com') return Role.SUPER_ADMIN;
    if (user.email?.endsWith('@trustverify.com')) return Role.ADMIN;
    if (user.trustScore && parseFloat(user.trustScore) >= 9.0) return Role.MODERATOR;
    return Role.USER;
  }

  static hasPermission(user: User, permission: Permission): boolean {
    const userRole = this.getUserRole(user);
    const permissions = rolePermissions[userRole] || [];
    return permissions.includes(permission);
  }

  static hasAnyPermission(user: User, permissions: Permission[]): boolean {
    return permissions.some(permission => this.hasPermission(user, permission));
  }

  static hasAllPermissions(user: User, permissions: Permission[]): boolean {
    return permissions.every(permission => this.hasPermission(user, permission));
  }

  static getUserPermissions(user: User): Permission[] {
    const userRole = this.getUserRole(user);
    return rolePermissions[userRole] || [];
  }

  static canAccessResource(user: User, resourceId: string, resourceType: string): boolean {
    const userRole = this.getUserRole(user);

    // Super admins can access everything
    if (userRole === Role.SUPER_ADMIN) return true;

    // Admins can access most resources
    if (userRole === Role.ADMIN) {
      return !['system_config', 'audit_logs'].includes(resourceType);
    }

    // Users can only access their own resources
    if (resourceType === 'user_profile' || resourceType === 'transaction' || resourceType === 'message') {
      return resourceId === user.id.toString();
    }

    return false;
  }
}

// RBAC Middleware
export const requirePermission = (permission: Permission) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.isAuthenticated() || !req.user) {
      logger.warn({
        ip: req.ip,
        endpoint: req.path,
        permission,
        reason: 'not_authenticated'
      }, 'Access denied: Not authenticated');

      return res.status(401).json({
        error: 'Authentication required',
        code: 'AUTHENTICATION_REQUIRED'
      });
    }

    if (!RBACService.hasPermission(req.user, permission)) {
      logger.warn({
        userId: req.user.id,
        userRole: RBACService.getUserRole(req.user),
        ip: req.ip,
        endpoint: req.path,
        permission,
        reason: 'insufficient_permissions'
      }, 'Access denied: Insufficient permissions');

      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'INSUFFICIENT_PERMISSIONS',
        required: permission
      });
    }

    logger.debug({
      userId: req.user.id,
      userRole: RBACService.getUserRole(req.user),
      endpoint: req.path,
      permission
    }, 'Access granted');

    next();
  };
};

export const requireAnyPermission = (permissions: Permission[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.isAuthenticated() || !req.user) {
      return res.status(401).json({
        error: 'Authentication required',
        code: 'AUTHENTICATION_REQUIRED'
      });
    }

    if (!RBACService.hasAnyPermission(req.user, permissions)) {
      logger.warn({
        userId: req.user.id,
        userRole: RBACService.getUserRole(req.user),
        ip: req.ip,
        endpoint: req.path,
        permissions,
        reason: 'insufficient_permissions'
      }, 'Access denied: Insufficient permissions');

      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'INSUFFICIENT_PERMISSIONS',
        required: permissions
      });
    }

    next();
  };
};

export const requireRole = (role: Role) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.isAuthenticated() || !req.user) {
      return res.status(401).json({
        error: 'Authentication required',
        code: 'AUTHENTICATION_REQUIRED'
      });
    }

    const userRole = RBACService.getUserRole(req.user);
    const roleHierarchy = [Role.USER, Role.MODERATOR, Role.ADMIN, Role.SUPER_ADMIN];
    const requiredRoleIndex = roleHierarchy.indexOf(role);
    const userRoleIndex = roleHierarchy.indexOf(userRole);

    if (userRoleIndex < requiredRoleIndex) {
      logger.warn({
        userId: req.user.id,
        userRole,
        requiredRole: role,
        ip: req.ip,
        endpoint: req.path,
        reason: 'insufficient_role'
      }, 'Access denied: Insufficient role');

      return res.status(403).json({
        error: 'Insufficient role',
        code: 'INSUFFICIENT_ROLE',
        required: role,
        current: userRole
      });
    }

    next();
  };
};

// Resource ownership check
export const requireResourceOwnership = (resourceType: string, getResourceId?: (req: Request) => string) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!req.isAuthenticated() || !req.user) {
      return res.status(401).json({
        error: 'Authentication required',
        code: 'AUTHENTICATION_REQUIRED'
      });
    }

    const userRole = RBACService.getUserRole(req.user);

    // Admins and above can access any resource
    if (userRole === Role.ADMIN || userRole === Role.SUPER_ADMIN) {
      return next();
    }

    const resourceId = getResourceId ? getResourceId(req) : req.params.id;

    if (!RBACService.canAccessResource(req.user, resourceId, resourceType)) {
      logger.warn({
        userId: req.user.id,
        resourceType,
        resourceId,
        ip: req.ip,
        endpoint: req.path,
        reason: 'not_resource_owner'
      }, 'Access denied: Not resource owner');

      return res.status(403).json({
        error: 'Access denied: You can only access your own resources',
        code: 'NOT_RESOURCE_OWNER'
      });
    }

    next();
  };
};

export default {
  Role,
  Permission,
  RBACService,
  requirePermission,
  requireAnyPermission,
  requireRole,
  requireResourceOwnership
};

import { z } from 'zod';

// Enhanced security configuration schema
const securityConfigSchema = z.object({
  // Core Security
  HTTPS_ONLY: z.string().transform(val => val === 'true').default('true'),
  FORCE_SSL: z.string().transform(val => val === 'true').default('true'),

  // Session Security
  SESSION_SECRET: z.string().min(64, 'Session secret must be at least 64 characters for production'),
  SESSION_LIFETIME: z.string().transform(Number).default('3600000'), // 1 hour
  SESSION_SECURE: z.string().transform(val => val === 'true').default('true'),

  // Rate Limiting
  RATE_LIMIT_WINDOW: z.string().transform(Number).default('900000'), // 15 minutes
  RATE_LIMIT_MAX: z.string().transform(Number).default('100'),
  AUTH_RATE_LIMIT: z.string().transform(Number).default('5'),

  // Password Policy
  MIN_PASSWORD_LENGTH: z.string().transform(Number).default('12'),
  REQUIRE_SPECIAL_CHARS: z.string().transform(val => val === 'true').default('true'),
  REQUIRE_NUMBERS: z.string().transform(val => val === 'true').default('true'),
  REQUIRE_UPPERCASE: z.string().transform(val => val === 'true').default('true'),

  // Two-Factor Authentication
  ENABLE_2FA: z.string().transform(val => val === 'true').default('false'),
  TOTP_ISSUER: z.string().default('TrustVerify'),

  // API Security
  API_KEY_LENGTH: z.string().transform(Number).default('32'),
  API_KEY_PREFIX: z.string().default('tv_'),
  JWT_SECRET: z.string().min(32).optional(),
  JWT_EXPIRY: z.string().default('24h'),

  // Encryption
  ENCRYPTION_ALGORITHM: z.string().default('aes-256-gcm'),
  ENCRYPTION_KEY: z.string().min(32).optional(),

  // Audit & Logging
  AUDIT_LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('info'),
  AUDIT_RETENTION_DAYS: z.string().transform(Number).default('2555'), // 7 years
  SECURITY_LOG_LEVEL: z.enum(['debug', 'info', 'warn', 'error']).default('warn'),

  // Compliance
  GDPR_ENABLED: z.string().transform(val => val === 'true').default('true'),
  SOC2_COMPLIANCE: z.string().transform(val => val === 'true').default('true'),
  PCI_COMPLIANCE: z.string().transform(val => val === 'true').default('false'),

  // Infrastructure Security
  WAF_ENABLED: z.string().transform(val => val === 'true').default('false'),
  DDOS_PROTECTION: z.string().transform(val => val === 'true').default('false'),

  // Development vs Production
  SECURITY_LEVEL: z.enum(['development', 'staging', 'production']).default('development'),

  // External Security Services
  CLOUDFLARE_API_KEY: z.string().optional(),
  SENDGRID_API_KEY: z.string().optional(),

  // Database Security
  DB_SSL_MODE: z.enum(['disable', 'require', 'verify-ca', 'verify-full']).default('require'),
  DB_ENCRYPTION: z.string().transform(val => val === 'true').default('true'),

  // File Upload Security
  MAX_FILE_SIZE: z.string().transform(Number).default('10485760'), // 10MB
  ALLOWED_FILE_TYPES: z.string().default('image/jpeg,image/png,application/pdf'),
  VIRUS_SCANNING: z.string().transform(val => val === 'true').default('false'),

  // Network Security
  CORS_ORIGINS: z.string().default(''),
  TRUSTED_PROXIES: z.string().default(''),

  // Monitoring & Alerting
  SECURITY_MONITORING: z.string().transform(val => val === 'true').default('true'),
  ALERT_WEBHOOK: z.string().url().optional(),
  SECURITY_EMAIL: z.string().email().optional(),
});

export type SecurityConfig = z.infer<typeof securityConfigSchema>;

// Validate and export security configuration
function validateSecurityConfig(): SecurityConfig {
  try {
    const config = securityConfigSchema.parse(process.env);

    // Additional production validations
    if (config.SECURITY_LEVEL === 'production') {
      if (!config.HTTPS_ONLY) {
        throw new Error('HTTPS is required in production');
      }
      if (!config.SESSION_SECURE) {
        throw new Error('Secure sessions are required in production');
      }
      if (config.MIN_PASSWORD_LENGTH < 12) {
        throw new Error('Minimum password length must be 12+ characters in production');
      }
    }

    return config;
  } catch (error) {
    if (error instanceof z.ZodError) {
      console.error('❌ Security configuration validation failed:');
      error.errors.forEach((err) => {
        console.error(`  ${err.path.join('.')}: ${err.message}`);
      });
      process.exit(1);
    }
    throw error;
  }
}

export const securityConfig = validateSecurityConfig();

// Security recommendations based on environment
export function getSecurityRecommendations(): string[] {
  const recommendations: string[] = [];

  if (!securityConfig.ENABLE_2FA) {
    recommendations.push('Enable Two-Factor Authentication for enhanced security');
  }

  if (!securityConfig.WAF_ENABLED && securityConfig.SECURITY_LEVEL === 'production') {
    recommendations.push('Enable Web Application Firewall (WAF) for production');
  }

  if (!securityConfig.DDOS_PROTECTION && securityConfig.SECURITY_LEVEL === 'production') {
    recommendations.push('Enable DDoS protection for production environments');
  }

  if (!securityConfig.VIRUS_SCANNING && securityConfig.SECURITY_LEVEL === 'production') {
    recommendations.push('Enable virus scanning for file uploads');
  }

  if (securityConfig.SESSION_LIFETIME > 7200000) { // 2 hours
    recommendations.push('Consider reducing session lifetime for better security');
  }

  if (!securityConfig.SECURITY_EMAIL) {
    recommendations.push('Configure security alert email for incident notifications');
  }

  return recommendations;
}

// Security metrics for monitoring
export interface SecurityMetrics {
  configurationScore: number;
  criticalIssues: string[];
  warnings: string[];
  recommendations: string[];
}

export function calculateSecurityScore(): SecurityMetrics {
  const criticalIssues: string[] = [];
  const warnings: string[] = [];
  let score = 100;

  // Critical security checks
  if (!securityConfig.HTTPS_ONLY) {
    criticalIssues.push('HTTPS not enforced');
    score -= 20;
  }

  if (!securityConfig.SESSION_SECURE && securityConfig.SECURITY_LEVEL === 'production') {
    criticalIssues.push('Insecure session configuration');
    score -= 15;
  }

  if (securityConfig.MIN_PASSWORD_LENGTH < 12) {
    criticalIssues.push('Weak password policy');
    score -= 10;
  }

  // Warning level checks
  if (!securityConfig.ENABLE_2FA) {
    warnings.push('Two-Factor Authentication disabled');
    score -= 5;
  }

  if (securityConfig.AUTH_RATE_LIMIT > 10) {
    warnings.push('Authentication rate limit too permissive');
    score -= 5;
  }

  if (!securityConfig.WAF_ENABLED && securityConfig.SECURITY_LEVEL === 'production') {
    warnings.push('Web Application Firewall not enabled');
    score -= 10;
  }

  return {
    configurationScore: Math.max(score, 0),
    criticalIssues,
    warnings,
    recommendations: getSecurityRecommendations()
  };
}

export default {
  securityConfig,
  getSecurityRecommendations,
  calculateSecurityScore
};

