  --warning: 38 92% 50%; /* #F59E0B - Amber */
  --warning-foreground: 222 84% 5%;
  --warning-hover: 38 92% 45%;
  --warning-light: 38 100% 95%;

  --destructive: 0 84% 60%; /* #E53E3E - Red */
  --destructive-foreground: 0 0% 100%;
  --destructive-hover: 0 84% 54%;
  --destructive-light: 0 100% 95%;

  --info: 213 87% 26%; /* Use primary navy for info */
  --info-foreground: 0 0% 100%;
  --info-light: 213 87% 95%;

  /* Surface & Background - Professional Gray Scale */
  --background: 210 20% 98%; /* #F8F9FB - Very light blue-gray */
  --foreground: 222 84% 5%; /* #0F172A - Deep navy text */
  --surface: 0 0% 100%; /* #FFFFFF - Pure white */
  --surface-raised: 0 0% 100%;
  --muted: 210 40% 96%; /* #F1F5F9 - Muted gray */
  --muted-foreground: 215 20% 45%; /* #64748B - Muted text */

  /* Popover & Dropdown - Clean White */
  --popover: 0 0% 100%; /* #FFFFFF */
  --popover-foreground: 222 84% 5%;
  --accent: 210 40% 96%; /* #F1F5F9 */
  --accent-foreground: 222 84% 5%;

  /* Border System */
  --border: 214 32% 91%; /* #E2E8F0 - Default border */
  --border-light: 210 40% 96%; /* #F1F5F9 - Light border */
  --border-dark: 215 25% 75%; /* Darker borders for emphasis */
  --input: 214 32% 91%;

  /* Focus & Ring States */
  --ring: 213 87% 26%; /* Primary navy for focus rings */
  --ring-offset: 0 0% 100%;

  /* Border Radius Scale - Modern & Glossy */
  --radius-sm: 0.375rem; /* 6px */
  --radius: 0.5rem; /* 8px */
  --radius-md: 0.75rem; /* 12px */
  --radius-lg: 1rem; /* 16px */
  --radius-xl: 1.5rem; /* 24px */

  /* Spacing System - Professional Standards */
  --spacing-xs: 8px;
  --spacing-sm: 16px;
  --spacing-md: 24px;
  --spacing-lg: 32px;
  --spacing-xl: 40px;
  --spacing-2xl: 48px;
  --spacing-3xl: 64px;

  /* Professional Shadow System - Glossy Effects */
  --shadow-xs: 0 1px 2px 0 rgba(10, 55, 120, 0.05);
  --shadow-sm: 0 2px 4px 0 rgba(10, 55, 120, 0.08), 0 1px 2px 0 rgba(10, 55, 120, 0.04);
  --shadow: 0 4px 8px -2px rgba(10, 55, 120, 0.1), 0 2px 4px -2px rgba(10, 55, 120, 0.06);
  --shadow-md: 0 8px 16px -4px rgba(10, 55, 120, 0.12), 0 4px 8px -4px rgba(10, 55, 120, 0.08);
  --shadow-lg: 0 16px 32px -8px rgba(10, 55, 120, 0.15), 0 8px 16px -8px rgba(10, 55, 120, 0.1);
  --shadow-xl: 0 24px 48px -12px rgba(10, 55, 120, 0.2), 0 12px 24px -12px rgba(10, 55, 120, 0.12);
  --shadow-2xl: 0 32px 64px -16px rgba(10, 55, 120, 0.25), 0 16px 32px -16px rgba(10, 55, 120, 0.15);

  /* Brand Gradients - Professional & Glossy */
  --gradient-primary: linear-gradient(135deg, #0A3778 0%, #0D4594 100%);
  --gradient-secondary: linear-gradient(135deg, #1DBF73 0%, #17A362 100%);
  --gradient-hero: linear-gradient(135deg, #0A3778 0%, #1DBF73 100%);
  --gradient-cta: linear-gradient(135deg, #1DBF73 0%, #0A3778 100%);
  --gradient-surface: linear-gradient(to bottom, #FFFFFF 0%, #F8F9FB 100%);
  --gradient-card: linear-gradient(145deg, #FFFFFF 0%, #F8F9FB 100%);

  /* Hover & Interactive Shadows */
  --shadow-hover: 0 20px 40px -10px rgba(10, 55, 120, 0.2);
  --shadow-focus: 0 0 0 3px rgba(10, 55, 120, 0.1);

  /* Animation Variables */
  --transition-fast: 150ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-base: 250ms cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 350ms cubic-bezier(0.4, 0, 0.2, 1);

  /* Typography Scale */
  --font-size-xs: 0.75rem; /* 12px */
  --font-size-sm: 0.875rem; /* 14px */
  --font-size-base: 1rem; /* 16px */
  --font-size-lg: 1.125rem; /* 18px */
  --font-size-xl: 1.25rem; /* 20px */
  --font-size-2xl: 1.5rem; /* 24px */
  --font-size-3xl: 1.875rem; /* 30px */
  --font-size-4xl: 2.25rem; /* 36px */
  --font-size-5xl: 3rem; /* 48px */
  --font-size-6xl: 3.75rem; /* 60px */

  /* Line Heights */
  --leading-none: 1;
  --leading-tight: 1.25;
  --leading-snug: 1.375;
  --leading-normal: 1.5;
  --leading-relaxed: 1.625;
  --leading-loose: 2;
}

/* Global Font Rendering - Crisp Text */
* {
  -webkit-font-smoothing: antialiased;
