    const num = parseFloat(amount) || 0;
    const trustVerifyFee = num * 0.025; // 2.5%
    const paymentFee = num * 0.029 + 0.30; // 2.9% + $0.30
    const totalFees = trustVerifyFee + paymentFee;
    const totalAmount = num + totalFees;

    return {
      subtotal: num,
      trustVerifyFee,
      paymentFee,
      totalFees,
      totalAmount,
    };
  };

