                        <div className="border rounded-lg p-4 bg-gray-50">
                          <TrustScoreWidget
                            domain={domain}
                            trustScore={trustScore}
                            riskLevel={riskLevel}
                            language={language}
                            size={size}
                            showEmbed={false}
                          />
