                        </div>
                        <Textarea
                          value={generateEmbedCode()}
                          readOnly
                          className="font-mono text-xs h-32"
                        />
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>
              )}
            </div>

            <div className={`${sizeClasses.subtitle} text-gray-400 mt-1 text-center`}>
              {t.verified}
