import { apiRequest } from "@/lib/queryClient";
import { Navigation } from "@/components/navigation";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Progress } from "@/components/ui/progress";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { 
  Upload, 
  FileText, 
  CheckCircle, 
  Clock, 
  AlertTriangle,
  Camera,
  CreditCard,
  Shield,
  User,
  MapPin,
  ArrowRight,
  ArrowLeft,
  Image,
  UserCheck
} from "lucide-react";

const verificationSchema = z.object({
  documentType: z.string().min(1, "Document type is required"),
  documentNumber: z.string().min(1, "Document number is required"),
  firstName: z.string().min(1, "First name is required"),
  lastName: z.string().min(1, "Last name is required"),
  dateOfBirth: z.string().min(1, "Date of birth is required"),
  address: z.string().min(1, "Address is required"),
  city: z.string().min(1, "City is required"),
  country: z.string().min(1, "Country is required"),
  postalCode: z.string().min(1, "Postal code is required"),
});

type VerificationForm = z.infer<typeof verificationSchema>;

export default function VerificationPage() {
  const { user } = useAuth();
  const [, setLocation] = useLocation();
  const [step, setStep] = useState(1);
  const [frontIdFile, setFrontIdFile] = useState<File | null>(null);
  const [backIdFile, setBackIdFile] = useState<File | null>(null);
  const [selfieFile, setSelfieFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors },
    setValue,
    watch
  } = useForm<VerificationForm>({
    resolver: zodResolver(verificationSchema),
  });

  const documentType = watch("documentType");

  // KYC status query
  const { data: kycStatus, isLoading: kycLoading, refetch } = useQuery({
    queryKey: ['/api/kyc/status'],
    queryFn: () => fetch('/api/kyc/status').then(res => res.json()),
    enabled: !!user
  });

  // KYC submission mutation
  const kycSubmissionMutation = useMutation({
    mutationFn: (formData: FormData) =>
      fetch('/api/kyc/submit', {
        method: 'POST',
        body: formData
      }).then(async res => {
        if (!res.ok) {
          const error = await res.json();
          throw new Error(error.message || 'Submission failed');
        }
        return res.json();
      }),
    onSuccess: (data) => {
      console.log("KYC verification submitted successfully:", data);
      setStep(4); // Success step
      refetch(); // Refresh KYC status
    },
    onError: (error: any) => {
      console.error("Error submitting verification:", error);
      alert(`Verification submission failed: ${error.message}`);
    }
  });

  const handleFileUpload = (file: File, type: 'front' | 'back' | 'selfie') => {
    if (file.size > 10 * 1024 * 1024) {
      alert("File size must be less than 10MB");
      return;
    }

    if (!file.type.startsWith('image/')) {
      alert("Please upload an image file");
      return;
    }

    switch (type) {
      case 'front':
        setFrontIdFile(file);
        break;
      case 'back':
        setBackIdFile(file);
        break;
      case 'selfie':
        setSelfieFile(file);
        break;
    }
  };

  const onSubmit = async (data: VerificationForm) => {
    setUploading(true);
    try {
      // Create FormData for file uploads
      const formData = new FormData();
      formData.append('documentType', data.documentType);
      formData.append('documentNumber', data.documentNumber);
      formData.append('firstName', data.firstName);
      formData.append('lastName', data.lastName);
      formData.append('dateOfBirth', data.dateOfBirth);
      formData.append('address', `${data.address}, ${data.city}, ${data.country}, ${data.postalCode}`);

      if (frontIdFile) {
        formData.append('frontImage', frontIdFile);
      }
      if (backIdFile) {
        formData.append('backImage', backIdFile);
      }
      if (selfieFile) {
        formData.append('selfieImage', selfieFile);
      }

      // Submit to real API
      kycSubmissionMutation.mutate(formData);
    } catch (error) {
      console.error("Error preparing verification:", error);
      setUploading(false);
    }
  };

  const getVerificationLevelInfo = () => {
    const currentLevel = user?.verificationLevel || "none";

    const levels = {
      none: {
        color: "bg-gray-100 text-gray-800",
        label: "Not Verified",
        description: "Complete identity verification to unlock higher transaction limits and build trust.",
        limits: "Transaction limit: £500"
      },
      basic: {
        color: "bg-blue-100 text-blue-800",
        label: "Basic Verified",
        description: "Basic verification completed. Upgrade to full verification for maximum benefits.",
        limits: "Transaction limit: £5,000"
      },
      full: {
        color: "bg-green-100 text-green-800",
        label: "Fully Verified",
        description: "Full verification completed. Enjoy unlimited transactions and maximum trust.",
        limits: "Transaction limit: Unlimited"
      }
    };

    return levels[currentLevel as keyof typeof levels] || levels.none;
  };

  const verificationInfo = getVerificationLevelInfo();

  const steps = [
    { number: 1, title: "Personal Information", description: "Provide your basic details" },
    { number: 2, title: "Document Upload", description: "Upload your ID documents" },
    { number: 3, title: "Identity Verification", description: "Take a verification selfie" },
    { number: 4, title: "Review & Submit", description: "Confirm your information" }
