                  const input = document.createElement('input');
                  input.type = 'file';
                  input.accept = 'image/*';
                  input.onchange = (e) => {
                    const newFile = (e.target as HTMLInputElement).files?.[0];
                    if (newFile) onFileChange(newFile);
                  };
                  input.click();
                }}
                className="border-blue-200 text-blue-600 hover:bg-blue-50"
              >
                Replace File
              </Button>
            </div>
          ) : (
