                variant="outline"
                onClick={() => {
                  const input = document.createElement('input');
                  input.type = 'file';
                  input.accept = 'image/*';
                  input.onchange = (e) => {
                    const file = (e.target as HTMLInputElement).files?.[0];
                    if (file) onFileChange(file);
                  };
                  input.click();
                }}
                className="border-blue-200 text-blue-600 hover:bg-blue-50"
              >
