  // Education Add-ons for TrustVerify Fraud Academy
  const educationAddOns = [
    {
      name: "Certification Exam",
      description: "Professional certification exam for TrustVerify Certified Fraud-Resilient Professional",
      price: 99,
      per: "per attempt"
    },
