import React, { useState, useEffect } from 'react';
import { useAuth } from '@/hooks/use-auth';
import { Navigation } from '@/components/navigation';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { 
  Shield, 
  AlertTriangle, 
  CheckCircle, 
  XCircle, 
  Activity, 
  Bug,
  Lock,
  Eye,
  Server,
  Database,
  Clock,
  Users,
  FileText,
  Zap
} from 'lucide-react';
import { apiRequest } from '@/lib/queryClient';

interface SecurityMetrics {
  configurationScore: number;
  criticalIssues: string[];
  warnings: string[];
  recommendations: string[];
  timestamp: string;
  environment: string;
}

interface PenTestResult {
  testId: string;
  testName: string;
  category: string;
  severity: 'critical' | 'high' | 'medium' | 'low' | 'info';
  status: 'pass' | 'fail' | 'warning';
  description: string;
  evidence?: any;
  remediation: string;
  timestamp: string;
}

export default function SecurityDashboard() {
  const { user } = useAuth();
  const [securityMetrics, setSecurityMetrics] = useState<SecurityMetrics | null>(null);
  const [penTestResults, setPenTestResults] = useState<PenTestResult[]>([]);
  const [loading, setLoading] = useState(true);
  const [runningPenTest, setRunningPenTest] = useState(false);

  useEffect(() => {
    loadSecurityStatus();
  }, []);

  const loadSecurityStatus = async () => {
    try {
      const response = await apiRequest('GET', '/api/security/status');
      const data = await response.json();
      setSecurityMetrics(data);
    } catch (error) {
      console.error('Failed to load security status:', error);
    } finally {
      setLoading(false);
    }
  };

  const runPenetrationTest = async () => {
    setRunningPenTest(true);
    try {
      const response = await apiRequest('POST', '/api/security/pentest');
      const data = await response.json();
      setPenTestResults(data.results);
    } catch (error) {
      console.error('Failed to run penetration test:', error);
    } finally {
      setRunningPenTest(false);
    }
  };

  const getSecurityScoreColor = (score: number) => {
    if (score >= 90) return 'text-green-600';
    if (score >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'critical': return 'bg-red-100 text-red-800 border-red-200';
      case 'high': return 'bg-orange-100 text-orange-800 border-orange-200';
      case 'medium': return 'bg-yellow-100 text-yellow-800 border-yellow-200';
