@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}

@layer utilities {
  .email-container {
    @apply truncate max-w-[120px] sm:max-w-[200px] md:max-w-none;
  }

  .text-truncate {
    @apply truncate;
  }

  .xs\:inline {
    @media (min-width: 475px) {
      @apply inline;
    }
  }

  .xs\:hidden {
    @media (min-width: 475px) {
      @apply hidden;
    }
  }
}

