                    <h4 className="font-medium text-gray-900">Python Flask API</h4>
                  </div>
                  <p className="text-sm text-gray-600 mb-3">Backend API integration with webhook handling</p>
                  <div className="flex space-x-2">
                    <Button size="sm" variant="outline" onClick={() => window.open('https://github.com/trustverify/python-flask-demo', '_blank')}>
                      <ExternalLink className="h-4 w-4 mr-1" />
                      View Code
                    </Button>
                    <Button size="sm" onClick={() => window.open('/postman-collection', '_blank')}>
                      <Download className="h-4 w-4 mr-1" />
                      Postman
                    </Button>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        </section>

        {/* Support CTA */}
        <Card className="bg-blue-50 border border-blue-200 shadow-sm mt-8">
          <CardContent className="p-6">
            <div className="flex items-center space-x-4">
              <Code className="h-8 w-8 text-blue-600" />
              <div className="flex-1">
                <h3 className="text-lg font-semibold text-blue-900">Need Custom Integration Help?</h3>
                <p className="text-blue-700">Our integration team can help you implement TrustVerify for your specific use case.</p>
              </div>
              <div className="space-x-2">
                <Button variant="outline" className="border-blue-300 text-blue-600 hover:bg-blue-100" onClick={() => window.open('/sdk-documentation', '_blank')}>
                  <ExternalLink className="h-4 w-4 mr-2" />
                  SDK Docs
                </Button>
                <Button className="bg-blue-600 hover:bg-blue-700 text-white" onClick={() => window.open('mailto:integrations@trustverify.com?subject=Custom Integration Request', '_blank')}>
                  Contact Team
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

