import { LiveChat } from "@/components/LiveChat";
import { 
  Phone, 
  Mail, 
  MessageCircle, 
  FileText, 
  Shield, 
  AlertTriangle, 
  Users, 
  Clock,
  CheckCircle,
  ExternalLink,
  BookOpen
} from "lucide-react";

export default function SupportCenter() {
  const { toast } = useToast();
  const [isChatOpen, setIsChatOpen] = useState(false);
  const [formData, setFormData] = useState({
    email: '',
    subject: '',
    description: '',
    priority: 'medium',
    category: 'general'
  });

  const createTicketMutation = useMutation({
    mutationFn: async (data: typeof formData) => {
      const response = await apiRequest('POST', '/api/support/tickets', data);
      return response.json();
    },
    onSuccess: (data) => {
      toast({
        title: "Support Ticket Created",
        description: `Your ticket ${data.ticket.id} has been created successfully. We'll respond within 24 hours.`,
      });
      setFormData({
        email: '',
        subject: '',
        description: '',
        priority: 'medium',
        category: 'general'
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create support ticket",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.email || !formData.subject || !formData.description) {
      toast({
        title: "Validation Error",
        description: "Please fill in all required fields",
        variant: "destructive",
      });
      return;
    }
    createTicketMutation.mutate(formData);
  };

  const supportOptions = [
    {
      title: "Live Chat Support",
      description: "Chat with our support team in real-time",
      icon: MessageCircle,
      action: "Start Chat",
      available: "24/7",
      color: "bg-green-500",
      onClick: () => setIsChatOpen(true)
    },
    {
      title: "Phone Support",
      description: "Speak directly with our UK support team",
      icon: Phone,
      contact: "+44 20 7123 4567",
      available: "Mon-Fri 9AM-6PM GMT",
      color: "bg-blue-500"
    },
    {
      title: "Email Support",
      description: "Send us a detailed message",
      icon: Mail,
      contact: "support@trustverify.io",
      available: "24-48h response",
      color: "bg-purple-500"
    }
  ];

  const quickActions = [
    {
      title: "User Guide",
      description: "Complete platform training manual",
      icon: BookOpen,
      link: "/user-guide",
      color: "bg-teal-500"
    },
    {
      title: "API Documentation",
      description: "Developer integration resources",
      icon: FileText,
      link: "/developers",
      color: "bg-indigo-500"
    },
    {
      title: "Security Center",
      description: "Learn about our security measures",
      icon: Shield,
      link: "/security",
      color: "bg-red-500"
    },
    {
      title: "Status Page",
      description: "Check platform status and uptime",
      icon: CheckCircle,
      link: "https://status.trustverify.io",
      external: true,
      color: "bg-green-600"
    }
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-900 to-blue-800 text-white py-16">
        <div className="max-w-7xl mx-auto px-6 lg:px-8">
          <div className="text-center">
            <h1 className="text-4xl font-bold mb-4">TrustVerify Support Center</h1>
            <p className="text-xl opacity-90 max-w-3xl mx-auto">
              Get the help you need to secure your transactions and protect your business
            </p>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 lg:px-8 py-12">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Contact Options */}
          <div className="lg:col-span-2 space-y-6">
            <div>
              <h2 className="text-2xl font-bold text-gray-900 mb-6">Contact Support</h2>
              <div className="grid gap-6">
                {supportOptions.map((option, index) => (
