      throw error;
    }
  }

  async generateRegulatoryReport(transaction, paymentData) {
    return await this.trustVerify.compliance.generateReport({
      transactionId: transaction.id,
      reportType: 'suspicious_activity',
      regulatoryBody: 'FinCEN',
