  // Progress methods
  async updateProgress(progress: Partial<InsertLmsProgress> & { userId: number; enrollmentId: number }): Promise<LmsProgress> {
    // Check if progress record exists
    const existingProgress = await db.select().from(lmsProgress)
      .where(and(
        eq(lmsProgress.userId, progress.userId),
        eq(lmsProgress.enrollmentId, progress.enrollmentId),
        progress.moduleId ? eq(lmsProgress.moduleId, progress.moduleId) : sql`module_id IS NULL`,
        progress.contentId ? eq(lmsProgress.contentId, progress.contentId) : sql`content_id IS NULL`
      ));

    if (existingProgress.length > 0) {
      // Update existing progress
      const [updatedProgress] = await db.update(lmsProgress)
        .set({ ...progress, updatedAt: new Date() })
        .where(eq(lmsProgress.id, existingProgress[0].id))
        .returning();
      return updatedProgress;
    } else {
      // Create new progress record
      const [newProgress] = await db.insert(lmsProgress).values(progress as InsertLmsProgress).returning();
      return newProgress;
    }
  }

