  async calculateEnrollmentProgress(enrollmentId: number): Promise<void> {
    // Get enrollment details
    const enrollment = await this.getEnrollmentById(enrollmentId);
    if (!enrollment) return;

    // Get all modules for the course
    const modules = await this.getModulesByCourse(enrollment.courseId);
    const totalModules = modules.length;

    // Get completed modules count
    const completedModules = await db.select({ count: count() })
      .from(lmsProgress)
      .where(and(
        eq(lmsProgress.enrollmentId, enrollmentId),
        eq(lmsProgress.status, "completed"),
        sql`module_id IS NOT NULL`
      ));

    const completed = completedModules[0]?.count || 0;
    const progressPercentage = totalModules > 0 ? (completed / totalModules) * 100 : 0;

    // Update enrollment progress
    await db.update(lmsEnrollments)
      .set({ 
        progress: progressPercentage.toFixed(2),
        status: progressPercentage >= 100 ? "completed" : "active",
        completedAt: progressPercentage >= 100 ? new Date() : null
      })
      .where(eq(lmsEnrollments.id, enrollmentId));
  }

  // Quiz methods
  async submitQuizAnswers(progressId: number, answers: any[]): Promise<{ totalScore: number; maxScore: number; passed: boolean }> {
    let totalScore = 0;
    let maxScore = 0;

    // Process each answer
    for (const answer of answers) {
      const { questionId, userAnswer, correctAnswer, points = 1 } = answer;
      const isCorrect = JSON.stringify(userAnswer) === JSON.stringify(correctAnswer);

      await this.createQuizAnswer({
        progressId,
        questionId,
        userAnswer,
        correctAnswer,
        isCorrect,
        points: isCorrect ? points.toString() : "0"
      });

      if (isCorrect) totalScore += points;
      maxScore += points;
    }

    const passed = maxScore > 0 ? (totalScore / maxScore) >= 0.7 : false; // 70% passing score

    return { totalScore, maxScore, passed };
  }

  async createQuizAnswer(answer: InsertLmsQuizAnswer): Promise<LmsQuizAnswer> {
    const [newAnswer] = await db.insert(lmsQuizAnswers).values(answer).returning();
    return newAnswer;
  }

  // Certification methods
  async issueCertificate(enrollmentId: number): Promise<LmsCertification> {
    const enrollment = await this.getEnrollmentById(enrollmentId);
    if (!enrollment) throw new Error("Enrollment not found");

    const course = await this.getCourseById(enrollment.courseId);
    if (!course) throw new Error("Course not found");

    const user = await this.getUser(enrollment.userId);
    if (!user) throw new Error("User not found");

    // Generate certificate number
    const certificateNumber = `TVC-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;

    const certificate: InsertLmsCertification = {
      userId: enrollment.userId,
      courseId: enrollment.courseId,
      enrollmentId,
      certificateNumber,
      certificateType: "course_completion",
      title: `TrustVerify Certified Fraud-Resilient Professional - ${course.title}`,
      finalScore: enrollment.progress,
      verificationUrl: `/api/lms/certificate/verify/${certificateNumber}`,
      certificateUrl: `/certificates/${certificateNumber}.pdf`
    };

    const [newCertificate] = await db.insert(lmsCertifications).values(certificate).returning();

    // Update enrollment to mark certificate earned
    await db.update(lmsEnrollments)
      .set({ certificateEarned: true, certificateIssuedAt: new Date() })
      .where(eq(lmsEnrollments.id, enrollmentId));

    return newCertificate;
  }

  async getUserCertificates(userId: number): Promise<LmsCertification[]> {
    return await db.select().from(lmsCertifications)
      .where(and(eq(lmsCertifications.userId, userId), eq(lmsCertifications.isRevoked, false)))
      .orderBy(desc(lmsCertifications.issuedAt));
  }

  async verifyCertificate(certificateNumber: string): Promise<LmsCertification | undefined> {
    const [certificate] = await db.select().from(lmsCertifications)
      .where(eq(lmsCertifications.certificateNumber, certificateNumber));
    return certificate;
  }

  // Business plan methods
  async createBusinessPlan(plan: InsertLmsBusinessPlan): Promise<LmsBusinessPlan> {
    const [newPlan] = await db.insert(lmsBusinessPlans).values(plan).returning();
    return newPlan;
  }

  async getBusinessPlanById(id: number): Promise<LmsBusinessPlan | undefined> {
    const [plan] = await db.select().from(lmsBusinessPlans).where(eq(lmsBusinessPlans.id, id));
    return plan;
  }

  async getBusinessPlansByAdmin(adminUserId: number): Promise<LmsBusinessPlan[]> {
    return await db.select().from(lmsBusinessPlans)
      .where(eq(lmsBusinessPlans.adminUserId, adminUserId))
      .orderBy(desc(lmsBusinessPlans.createdAt));
  }

  async updateBusinessPlan(id: number, updates: Partial<LmsBusinessPlan>): Promise<LmsBusinessPlan | undefined> {
    const [updatedPlan] = await db.update(lmsBusinessPlans)
      .set({ ...updates, updatedAt: new Date() })
      .where(eq(lmsBusinessPlans.id, id))
      .returning();
    return updatedPlan;
  }

  // Business enrollment methods
  async createBusinessEnrollment(enrollment: InsertLmsBusinessEnrollment): Promise<LmsBusinessEnrollment> {
    const [newEnrollment] = await db.insert(lmsBusinessEnrollments).values(enrollment).returning();
    return newEnrollment;
  }

  async getBusinessEnrollments(businessPlanId: number): Promise<LmsBusinessEnrollment[]> {
    return await db.select().from(lmsBusinessEnrollments)
      .where(eq(lmsBusinessEnrollments.businessPlanId, businessPlanId))
      .orderBy(lmsBusinessEnrollments.enrolledAt);
  }

  async getBusinessProgressSummary(businessPlanId: number): Promise<any> {
    const enrollments = await this.getBusinessEnrollments(businessPlanId);

    const summary = {
      totalEmployees: enrollments.length,
      activeEnrollments: enrollments.filter(e => e.status === "active").length,
      completedEnrollments: enrollments.filter(e => e.status === "completed").length,
      averageProgress: 0,
      certificatesIssued: 0
    };

    // Calculate average progress (this would need more complex queries in real implementation)
    summary.averageProgress = enrollments.length > 0 ? 
      enrollments.reduce((acc, e) => acc + (parseFloat(e.progress || "0")), 0) / enrollments.length : 0;

    // Count certificates (simplified)
    const certificates = await db.select({ count: count() })
      .from(lmsCertifications)
      .where(sql`user_id IN (${enrollments.map(e => e.userId).join(',')})`);

    summary.certificatesIssued = certificates[0]?.count || 0;

    return summary;
  }
}

export const storage = new DatabaseStorage();

