                <AlertDescription>
                  <strong>{t.cleanRecord}:</strong> {t.noReports}
                </AlertDescription>
              </Alert>
            )}
          </CardContent>
        </Card>

        {/* Security Disclaimer */}
        <SecurityDisclaimer variant="compact" />
      </div>
    </div>
  );
}

